#include <vector>
#include <algorithm>

class Solution {
public:
    int maxFrequency(std::vector<int>& nums, int k, int numOperations) {
        std::sort(nums.begin(), nums.end());
        std::vector<int> candidates;
        candidates.reserve(nums.size() * 3);
        for (int x : nums) {
            candidates.push_back(x);
            candidates.push_back(x - k);
            candidates.push_back(x + k);
        }
        std::sort(candidates.begin(), candidates.end());
        candidates.erase(std::unique(candidates.begin(), candidates.end()), candidates.end());

        int ans = 0;
        for (int v : candidates) {
            auto it1 = std::lower_bound(nums.begin(), nums.end(), v - k);
            auto it2 = std::upper_bound(nums.begin(), nums.end(), v + k);
            int total_in_range = it2 - it1;

            auto eq1 = std::lower_bound(nums.begin(), nums.end(), v);
            auto eq2 = std::upper_bound(nums.begin(), nums.end(), v);
            int exact = eq2 - eq1;

            int achievable = exact + std::min(numOperations, total_in_range - exact);
            ans = std::max(ans, achievable);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxFrequency(int[] nums, int k, int numOperations) {
        Arrays.sort(nums);
        TreeSet<Integer> set = new TreeSet<>();
        for (int x : nums) {
            set.add(x);
            set.add(x - k);
            set.add(x + k);
        }

        int ans = 0;
        for (int v : set) {
            int left = lowerBound(nums, v - k);
            int right = upperBound(nums, v + k);
            int totalInRange = right - left;

            int eqLeft = lowerBound(nums, v);
            int eqRight = upperBound(nums, v);
            int exact = eqRight - eqLeft;

            int achievable = exact + Math.min(numOperations, totalInRange - exact);
            ans = Math.max(ans, achievable);
        }
        return ans;
    }

    private int lowerBound(int[] a, int target) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] >= target) r = m;
            else l = m + 1;
        }
        return l;
    }

    private int upperBound(int[] a, int target) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] > target) r = m;
            else l = m + 1;
        }
        return l;
    }
}

var maxFrequency = function(nums, k, numOperations) {
    nums.sort((a, b) => a - b);
    const candSet = new Set();
    for (const x of nums) {
        candSet.add(x);
        candSet.add(x - k);
        candSet.add(x + k);
    }

    function lowerBound(target) {
        let l = 0, r = nums.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (nums[m] >= target) r = m;
            else l = m + 1;
        }
        return l;
    }

    function upperBound(target) {
        let l = 0, r = nums.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (nums[m] > target) r = m;
            else l = m + 1;
        }
        return l;
    }

    let ans = 0;
    for (const v of candSet) {
        const left = lowerBound(v - k);
        const right = upperBound(v + k);
        const totalInRange = right - left;

        const exact = upperBound(v) - lowerBound(v);
        const achievable = exact + Math.min(numOperations, totalInRange - exact);
        if (achievable > ans) ans = achievable;
    }
    return ans;
};
